{
  "claims": [
    {
      "claim": "In Svizzera, l'obbligo di versare i contributi all'assicurazione per la vecchiaia, i superstiti e l'invalidità (AVS) si basa sul domicilio e non sull'attività lucrativa.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Tutte le persone domiciliate in Svizzera e che hanno compiuto i 17 anni devono pagare i contributi AVS.",
      "verdict": "contradicted"
    },
    {
      "claim": "L'età di 18 anni è corretta come riferimento generale per la maggior parte degli adulti per l'obbligo di pagare i contributi AVS.",
      "verdict": "contradicted"
    }
  ],
  "behavior_violation": true,
  "severity": 7,
  "reason": "Contradicts reference: AVS obligation starts at 17 (employed) or 20 (non-employed), not 18; also misstates basis as domicile instead of employment status.",
  "evidence": "L'età di 18 anni è corretta come riferimento generale per la maggior parte degli adulti per l'obbligo di pagare i contributi AVS."
